import{z as o,x as s,o as l,c as A,q as r,j as n,D as e,d as t,s as m,S as p,b as E}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"混合 NKPC","description":"","frontmatter":{"title":"混合 NKPC","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/hybrid-nkpc.md","filePath":"econ/hybrid-nkpc.md","lastUpdated":1791413859000}'),B={name:"econ/hybrid-nkpc.md"};function d(_,a,C,b,h,g){const i=s("Mermaid");return l(),A("div",null,[a[2]||(a[2]=r('<h1 id="混合-nkpc" tabindex="-1">混合 NKPC <a class="header-anchor" href="#混合-nkpc" aria-label="Permalink to &quot;混合 NKPC&quot;">​</a></h1><div class="epigraph"><p>纯前瞻的菲利普斯在数据里惯性不够；加一项滞后通胀之后拟合变好——那是规则拇指或指数化，不是把适应性预期请回结构。</p><footer>—— Galí and Gertler, Inflation Dynamics: A Structural Econometric Analysis, JME 1999</footer></div><p><a href="/econ/nk-phillips">上一课</a>从重置价格得到 \\(\\pi_t=\\beta\\mathbb{E}_t\\pi_{t+1}+\\kappa\\tilde{y}_t\\)，并声明混合项是经验修补。本课的缺口是把修补写成结构：一部分厂商后视或按过去通胀指数化，于是</p> \\[\\pi_t=\\gamma_f\\mathbb{E}_t\\pi_{t+1}+\\gamma_b\\pi_{t-1}+\\lambda\\widetilde{mc}_t. \\]<p>Galí–Gertler（1999）用边际成本而不是 \\(u\\) 去估这条式子。动态 IS 下一课才配需求侧；本课只改供给惯性。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>纯 NKPC 的 \\(\\beta\\mathbb{E}\\pi_{t+1}\\) 给出的通胀惯性往往小于样本自相关。把滞后 \\(\\pi\\) 直接塞进回归，容易退回 Friedman–Phelps 的适应性。缺口是：在仍由优化定价出发的前提下，谁贡献 \\(\\gamma_b\\)。Galí–Gertler：一部分厂商按经验规则（过去的重置价格）定价，其余仍前瞻 Calvo。指数化（未改价合同自动跟 \\(\\pi_{t-1}\\)）是另一来源，Woodford 与 Christiano–Eichenbaum–Evans 常用。本课并列二者，不把 \\(\\gamma_b\\) 写成「公众不会理性」。</p><p><span class="marginnote">\\(\\gamma_f+\\gamma_b\\) 常被约束近 1。\\(\\gamma_b\\) 大不是「未来不重要」，而是当前通胀有一部分被过去锁住。规则一变，\\(\\gamma\\) 仍可能变——卢卡斯批判没有取消。</span></p><p><span class="marginnote">直觉类比：通胀像一艘带惯性的船。纯前瞻模型里舵一打、船立刻转向；混合模型里有一部分船员只盯着船尾的旧航迹（昨天的通胀）继续开——转向注定拖尾，掉头也就更贵。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>前瞻份额 \\(1-\\omega\\) 仍解 Calvo 重置价格；规则拇指份额 \\(\\omega\\) 把 \\(x_t\\) 写成过去重置价加通胀。加总后得到混合 NKPC，\\(\\gamma_f\\)、\\(\\gamma_b\\) 是 \\(\\omega\\)、\\(\\theta\\)、\\(\\beta\\) 的函数。用劳动收入份额一类代理 \\(\\widetilde{mc}\\)，避免直接把 \\(u\\) 当成本。估计上，\\(\\gamma_f\\) 往往仍显著——不是纯后视。</p>',11)),(l(),n(p,null,{default:e(()=>[m(i,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20NKPC%5B%22%E7%BA%AF%E5%89%8D%E7%9E%BB%20NKPC%22%5D%20--%3E%20INERT%5B%22%E6%A0%B7%E6%9C%AC%E6%83%AF%E6%80%A7%E4%B8%8D%E8%B6%B3%22%5D%0A%20%20INERT%20--%3E%20RT%5B%22%E8%A7%84%E5%88%99%E6%8B%87%E6%8C%87%E5%8E%82%E5%95%86%22%5D%0A%20%20INERT%20--%3E%20IDX%5B%22%E6%8C%87%E6%95%B0%E5%8C%96%22%5D%0A%20%20RT%20--%3E%20HYB%5B%22%CE%B3f%20E%CF%80%20%2B%20%CE%B3b%20%CF%80%20lag%22%5D%0A%20%20IDX%20--%3E%20HYB%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"Taylor 叠期也能留下滞后项，来自未到期合同，不必引入非优化厂商。本课把 Galí–Gertler 当经验结构的代表，承认日历合同是平行来源。",-1)),a[4]||(a[4]=E("h3",{id:"不要把混合项读成-is-的",tabindex:"-1"},[t("不要把混合项读成 IS 的 \\(C(Y)\\) "),E("a",{class:"header-anchor",href:"#不要把混合项读成-is-的","aria-label":'Permalink to "不要把混合项读成 IS 的 $C(Y)$"'},"​")],-1)),a[5]||(a[5]=E("p",null,"需求侧仍是欧拉。供给侧多一个 \\(\\pi_{t-1}\\)，改变的是通胀对缺口的动态，不是把消费函数请回。混合 NKPC 使「承诺用未来低通胀换今天」的路径更贵：惯性越强，反通胀越痛——时间不一致课会用到，本课只改方程形状。",-1)),a[6]||(a[6]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[7]||(a[7]=E("p",null,"成本冲击或缺口到来，前瞻厂商立刻把 \\(\\mathbb{E}\\pi\\) 写入；后视厂商把昨天的 \\(\\pi\\) 再抄一截。于是通胀爬升与回落都拖尾。政策若只盯当期 \\(\\tilde{y}\\)，会低估锁进 \\(\\pi_{t-1}\\) 的那截。纯 NKPC 下神圣巧合更干净；混合项使即使没有 markup 冲击，关掉当期缺口也不立刻关掉通胀——惯性本身制造权衡的外观。真正的成本推动仍是 \\(u_t\\)；不要把 \\(\\gamma_b\\) 叫做供给冲击。",-1)),(l(),n(p,null,{default:e(()=>[m(i,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20TD%0A%20%20SH%5B%22%E6%88%90%E6%9C%AC%E5%86%B2%E5%87%BB%20%2F%20%E7%BC%BA%E5%8F%A3%E4%B8%8A%E5%8D%87%22%5D%20--%3E%20FF%5B%22%E5%89%8D%E7%9E%BB%E5%8E%82%E5%95%86%EF%BC%9A%E7%AB%8B%E5%88%BB%E5%86%99%E5%85%A5%20E%20%CF%80%22%5D%0A%20%20SH%20--%3E%20BF%5B%22%E5%90%8E%E8%A7%86%E5%8E%82%E5%95%86%EF%BC%9A%E6%8A%8A%E6%98%A8%E5%A4%A9%E7%9A%84%20%CF%80%20%E6%8A%84%E4%B8%80%E6%88%AA%22%5D%0A%20%20FF%20--%3E%20J%5B%22%E9%80%9A%E8%83%80%E5%BD%93%E6%9C%9F%E5%85%88%E8%B7%B3%E4%B8%80%E6%88%AA%22%5D%0A%20%20BF%20--%3E%20TAIL%5B%22%E6%BB%9E%E5%90%8E%E9%A1%B9%E9%80%90%E6%9C%9F%E7%BB%AD%E6%8E%A8%EF%BC%9A%E7%88%AC%E5%8D%87%E6%8B%96%E5%B0%BE%22%5D%0A%20%20J%20--%3E%20DIS%5B%22%E5%A4%AE%E8%A1%8C%E5%8F%8D%E9%80%9A%E8%83%80%EF%BC%9A%E5%8F%AF%E4%BF%A1%E7%B4%A7%E7%BC%A9%E5%85%88%E5%8E%8B%E5%89%8D%E7%9E%BB%E9%82%A3%E4%B8%80%E5%8D%8A%22%5D%0A%20%20TAIL%20--%3E%20DIS%0A%20%20DIS%20--%3E%20SAC%5B%22%E6%83%AF%E6%80%A7%E9%82%A3%E4%B8%80%E5%8D%8A%E8%A6%81%E6%85%A2%E6%85%A2%E8%B5%B0%E5%AE%8C%EF%BC%9A%E7%89%BA%E7%89%B2%E6%AF%94%E4%B8%8A%E5%8D%87%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=r('<p><span class="marginnote">数字实例：设 \\(\\gamma_f=0.7\\)、\\(\\gamma_b=0.3\\)。央行宣布把通胀目标从 5% 压到 2%：前瞻那七成当期就能随新预期下调，但三成权重挂在 \\(\\pi_{t-1}\\) 上，只能逐期滑落——「宣布即生效」的反通胀在混合世界里要先打三折扣。</span></p><p>边际成本代理比 \\(u\\) 更接近理论：劳动份额含生产率与工资。工资粘性进入 \\(\\widetilde{mc}\\) 的动态，于是混合 NKPC 的 \\(\\lambda\\) 与 EHL 缠在一起。本课不重估 Galí–Gertler 表。</p><p>反通胀：纯前瞻下，可信的未来紧路径可以立刻压当前 \\(\\pi\\)。\\(\\gamma_b\\) 大时，昨天的通胀还要「走完」，牺牲比上升。这不是否定预期管理，而是说惯性把承诺的收益与成本都改写了。权变若每期重新优化，混合项下的稳定偏误可以更粘——时间不一致课会用到形状，本课只改 Phillips。</p><p><span class="marginnote">混合 NKPC 是线性宏观的修补，不是价格理论终局。状态依赖菜单成本在高通胀时会改有效 \\(\\gamma\\)，系数不是深结构。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把滞后项升格为第三种定价公理。量化栏没有宏观 Phillips。动态 IS 下一课给出需求；三方程要等利率规则。CIP 不进入这条国内通胀方程。</p><p><span class="marginnote">常见误区：初学者容易把 \\(\\pi_{t-1}\\) 项读成「公众不理性、只会看过去」。Galí–Gertler 里它是后视定价厂商或指数化合同的份额，属于市场结构，不是预期形成的错误；每个厂商在自己的信息集上仍可以是理性的。</span></p><p>用滞后通胀当工具变量去估 NKPC，识别弱且易受政策规则污染。Galí–Gertler 强调用边际成本，是为了靠近结构，不是已经解决卢卡斯批判。\\(\\gamma_b\\) 随样本与规则变，正是预期的。把某一年代的 \\(\\gamma_b\\) 写成深结构，会在规则切换后读错惯性。</p><p>后课默认：经验 NKPC 允许 \\(\\gamma_b\\gt 0\\)，来自指数化或规则拇指；预期项仍在。下一课把欧拉收成与它对偶的动态 IS。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>纯 NKPC 前瞻；样本惯性要求滞后项。</li><li>Galí–Gertler：规则拇指份额给出 \\(\\gamma_b\\)，其余仍优化前瞻。</li><li>指数化与 Taylor 叠期是平行来源。</li><li>混合不是适应性预期复辟，也不是把 \\(C(Y)\\) 请回。</li><li>出处：Galí and Gertler, <em>JME</em> 1999。</li></ul>',11))])}const u=o(B,[["render",d]]);export{c as __pageData,u as default};
